-- chickenbot.db, schema v2.
--
-- A snapshot, not the source: the shape is created by the SCHEMA constant
-- in the code. This file is here so a later version can be diffed against
-- it, and so a fork can see exactly what a version was. Regenerated by
-- deploy/schema/dump.py; see docs/schema.md.

PRAGMA user_version = 2;

CREATE TABLE activity (
    id      INTEGER PRIMARY KEY,
    ts_ms      INTEGER NOT NULL,
    kind    TEXT NOT NULL DEFAULT '',
    realm   TEXT NOT NULL DEFAULT '',
    room    TEXT NOT NULL DEFAULT '',
    nick    TEXT NOT NULL DEFAULT '',
    account TEXT NOT NULL DEFAULT '',
    command TEXT NOT NULL DEFAULT '',
    outcome TEXT NOT NULL DEFAULT '',
    llm     TEXT NOT NULL DEFAULT '',
    model   TEXT NOT NULL DEFAULT '',
    served  TEXT NOT NULL DEFAULT '',
    tools   TEXT NOT NULL DEFAULT '',
    error   TEXT NOT NULL DEFAULT '',
    cost    REAL NOT NULL DEFAULT 0,
    ms      INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE alias (
    realm     TEXT NOT NULL,
    handle    TEXT NOT NULL,
    person_id INTEGER NOT NULL REFERENCES person(id) ON DELETE CASCADE,
    source    TEXT NOT NULL DEFAULT 'cli',  -- who said so: cli, or an account
    added_at_ms  INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (realm, handle)
);

CREATE TABLE bot (
    realm    TEXT NOT NULL,
    handle   TEXT NOT NULL,
    author   TEXT NOT NULL DEFAULT 'cli',
    added_at_ms INTEGER NOT NULL,
    PRIMARY KEY (realm, handle)
);

CREATE TABLE chatlog (
    id        INTEGER PRIMARY KEY,
    ts_ms        INTEGER NOT NULL,
    realm     TEXT NOT NULL DEFAULT 'irc',
    channel   TEXT NOT NULL,
    nick      TEXT NOT NULL,
    nick_key  TEXT NOT NULL DEFAULT '',
    account   TEXT NOT NULL DEFAULT '',
    kind      TEXT NOT NULL DEFAULT 'privmsg',
    text      TEXT NOT NULL,
    note      TEXT NOT NULL DEFAULT '',  -- its own aside; see annotate_reply
    note_cut  INTEGER NOT NULL DEFAULT 0  -- characters the cap took off it
);

CREATE TABLE cursor (
    watch_id INTEGER NOT NULL REFERENCES watch(id) ON DELETE CASCADE,
    feed     TEXT NOT NULL,
    last_id  TEXT NOT NULL DEFAULT '',
    etag     TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (watch_id, feed)
);

CREATE TABLE greeting (
    realm TEXT NOT NULL,
    room  TEXT NOT NULL,
    nick_key TEXT NOT NULL,
    day   TEXT NOT NULL,      -- YYYY-MM-DD, local
    PRIMARY KEY (realm, room, nick_key)
);

CREATE TABLE job (
    id         INTEGER PRIMARY KEY,
    due_at_ms     INTEGER NOT NULL,
    realm  TEXT NOT NULL,
    room       TEXT NOT NULL,
    nick       TEXT NOT NULL,
    account    TEXT NOT NULL,
    is_group   INTEGER NOT NULL DEFAULT 1,
    command    TEXT NOT NULL,
    created_at_ms INTEGER NOT NULL
);

CREATE TABLE llm_call (
    id       INTEGER PRIMARY KEY,
    ts_ms       INTEGER NOT NULL,
    reason   TEXT NOT NULL DEFAULT '',   -- what asked: ask, follow, bartender, vibe, barfly
    realm    TEXT NOT NULL DEFAULT '',
    room     TEXT NOT NULL DEFAULT '',
    nick     TEXT NOT NULL DEFAULT '',
    request  TEXT NOT NULL DEFAULT '',   -- system, history and the turn, as sent
    response TEXT NOT NULL DEFAULT '',   -- as returned, before chunking or prefixing
    model    TEXT NOT NULL DEFAULT '',
    served   TEXT NOT NULL DEFAULT '',
    tool_calls TEXT NOT NULL DEFAULT '[]',  -- json: name, args and result, in order
    details  TEXT NOT NULL DEFAULT '[]',   -- json: one entry per HTTP leg of the turn
    ms       INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE membership (
    realm      TEXT NOT NULL,
    room       TEXT NOT NULL,
    person_id  INTEGER NOT NULL REFERENCES person(id) ON DELETE CASCADE,
    nick       TEXT NOT NULL DEFAULT '',   -- the last one they used there
    first_seen_ms INTEGER NOT NULL,
    last_seen_ms  INTEGER NOT NULL,
    PRIMARY KEY (realm, room, person_id)
);

CREATE TABLE moderation (
    id     INTEGER PRIMARY KEY,
    ts_ms     INTEGER NOT NULL,
    realm  TEXT NOT NULL,
    room   TEXT NOT NULL,
    action TEXT NOT NULL,
    target TEXT NOT NULL,
    actor  TEXT NOT NULL DEFAULT '',   -- the account that asked for it
    result TEXT NOT NULL DEFAULT ''
);

CREATE TABLE person (
    id         INTEGER PRIMARY KEY,
    notes      TEXT NOT NULL DEFAULT '',
    observed   TEXT NOT NULL DEFAULT '',
    facts      TEXT NOT NULL DEFAULT '{}',
    updated_at_ms INTEGER NOT NULL
);

CREATE TABLE presence (
    realm TEXT NOT NULL,
    room  TEXT NOT NULL,
    dow   INTEGER NOT NULL,   -- 0 = Monday, local time
    hour  INTEGER NOT NULL,
    lines INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (realm, room, dow, hour)
);

CREATE TABLE revision (
    id     INTEGER PRIMARY KEY,
    kind   TEXT NOT NULL,              -- soul | person | room
    key    TEXT NOT NULL DEFAULT '',   -- '' for the soul, realm/account for a person
    text   TEXT NOT NULL,              -- the value as of this change
    author TEXT NOT NULL DEFAULT '',
    ts_ms     INTEGER NOT NULL
);

CREATE TABLE room (
    realm      TEXT NOT NULL,
    name       TEXT NOT NULL,
    notes      TEXT NOT NULL DEFAULT '',
    observed   TEXT NOT NULL DEFAULT '',
    checked_at_ms INTEGER NOT NULL DEFAULT 0,
    updated_at_ms INTEGER NOT NULL,
    PRIMARY KEY (realm, name)
);

CREATE TABLE schema_history (
    version    INTEGER PRIMARY KEY,
    applied_ms INTEGER NOT NULL,
    by         TEXT NOT NULL DEFAULT ''   -- the release that applied it
);

CREATE TABLE setting (
    key        TEXT PRIMARY KEY,
    value      TEXT NOT NULL,
    author     TEXT NOT NULL DEFAULT 'cli',
    updated_at_ms INTEGER NOT NULL
);

CREATE TABLE soul (
    id         INTEGER PRIMARY KEY CHECK (id = 1),
    text       TEXT NOT NULL,
    updated_at_ms INTEGER NOT NULL
);

CREATE TABLE soul_patch (
    id      TEXT PRIMARY KEY,
    at_ms   INTEGER NOT NULL,
    outcome TEXT NOT NULL DEFAULT ''   -- applied | by-hand
);

CREATE TABLE topic_log (
    id    INTEGER PRIMARY KEY,
    ts_ms    INTEGER NOT NULL,
    realm TEXT NOT NULL,
    room  TEXT NOT NULL,
    topic TEXT NOT NULL,
    who   TEXT NOT NULL DEFAULT ''     -- '' means it was already there when we arrived
);

CREATE TABLE watch (
    id        INTEGER PRIMARY KEY,
    realm     TEXT NOT NULL DEFAULT 'irc',
    owner     TEXT NOT NULL,
    repo      TEXT NOT NULL,
    channel   TEXT NOT NULL,
    feeds     TEXT NOT NULL DEFAULT 'releases',
    added_by  TEXT NOT NULL DEFAULT '',
    added_at_ms  INTEGER NOT NULL,
    UNIQUE (realm, owner, repo, channel)
);

CREATE INDEX activity_ts ON activity (ts_ms DESC);

CREATE INDEX alias_handle ON alias (handle COLLATE NOCASE);

CREATE INDEX chatlog_room_id ON chatlog (realm, channel, id DESC);

CREATE INDEX chatlog_who_id  ON chatlog (realm, nick_key, id DESC);

CREATE INDEX job_due ON job (due_at_ms);

CREATE INDEX llm_call_ts ON llm_call (ts_ms DESC);

CREATE INDEX moderation_room ON moderation (realm, room, ts_ms DESC);

CREATE INDEX revision_key ON revision (kind, key, id DESC);

CREATE INDEX topic_log_room ON topic_log (realm, room, id DESC);
